(7564160, 1213231, 29269, '<td valign="top">I love this! Favorite of the challenge!</td>', 'I love this! Favorite of the challenge!', '2018-03-28 02:48:58.000000', NULL, 1),
(7564171, 1212924, 67258, '<td valign="top">A really pleasing photo, although for this challenge I would have appreciated a rather wider shot to give a greater sense of emptiness.  love the title.</td>', 'A really pleasing photo, although for this challenge I would have appreciated a rather wider shot to give a greater sense of emptiness.  love the title.', '2018-03-28 08:00:35.000000', NULL, 1),
(7564172, 1213231, 67258, '<td valign="top">love the processing of this, and the very limited colour palette. 8.</td>', 'love the processing of this, and the very limited colour palette. 8.', '2018-03-28 08:02:18.000000', NULL, 1),
(7564173, 1212990, 67258, '<td valign="top">somewhat disturbing - not sure if I have unpicked the story here as you intended, but that doesn''t matter. made me think, which I always appreciate.</td>', 'somewhat disturbing - not sure if I have unpicked the story here as you intended, but that doesn''t matter. made me think, which I always appreciate.', '2018-03-28 08:03:40.000000', NULL, 1),
(7564174, 1212954, 67258, '<td valign="top">a competent photo, although a little saccharine for my tastes.  I actually think it would have  worked well for the theme with just the beachscape background - but then, it would be a different photo.</td>', 'a competent photo, although a little saccharine for my tastes.  I actually think it would have  worked well for the theme with just the beachscape background - but then, it would be a different photo.', '2018-03-28 08:06:01.000000', NULL, 1),
